# Housing simulator, long texts (policy cards), part 1. Keys come from hkeys.json by position; each entry carries the
# first words of its English so a changed or reordered key is skipped instead of mistranslated.
import json, os
K = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'hkeys.json'), encoding='utf-8'))
def mk(D):
    T = {}
    for i, v in D.items():
        pre, tr = v[0], v[1:]
        if i < len(K) and K[i].startswith(pre): T[K[i]] = tuple(tr)
    return T

T = mk({
0: ('Stalled in', 'Estancado en Springfield, 2026', '在州议会搁浅，2026', 'Utknęło w Springfield, 2026'),
1: ("Gov. Pritzker", 'El paquete del gobernador Pritzker legalizaría dúplex, tríplex y unidades en el patio trasero en lotes residenciales de todo el estado, con más viviendas en lotes más grandes. No hubo votaciones en comité en la sesión de 2026; él dice que seguirá insistiendo.',
    '普利兹克州长的方案将在全州住宅地块上合法化双户、三户住宅和后院单元，较大的地块可建更多住房。2026 年会期内没有进行委员会表决；他表示会继续推动。',
    'Pakiet gubernatora Pritzkera zalegalizowałby domy dwu- i trzyrodzinne oraz domki na podwórkach na działkach mieszkalnych w całym stanie, z większą liczbą mieszkań na większych działkach. W sesji 2026 nie było głosowań w komisjach; gubernator zapowiada, że nie odpuści.'),
2: ('Every lot with 1–4 homes gets at least 3', 'Todo lote con 1 a 4 viviendas recibe al menos zonificación para un edificio de 3 departamentos.', '每块有 1–4 套住房的地块至少获得三户楼分区。', 'Każda działka z 1–4 mieszkaniami dostaje co najmniej strefę dla domu trzyrodzinnego.'),
3: ('In effect since', 'Vigente desde 2021', '自 2021 年起生效', 'Obowiązuje od 2021'),
4: ('Projects of 10+', 'Los proyectos de 10 o más viviendas que necesitan un cambio de zonificación, terreno de la ciudad o dinero de la ciudad deben rentar entre el 10% y el 20% de las unidades por debajo del mercado, con precios para hogares que ganan en promedio el 60% del ingreso medio del área. El resto del edificio paga esas unidades, así que un requisito más alto significa más viviendas asequibles en cada edificio, pero algunos edificios dejan de ser rentables y nunca se construyen. Quitarlo construye más viviendas pero ninguna asequible, y elimina las cuotas que financian vivienda asequible y ayuda con la renta.',
    '需要更改分区、使用市有土地或市政资金的 10 套以上住房项目，必须以低于市场的价格出租 10–20% 的单元，价格按平均收入为地区中位收入 60% 的家庭设定。这些单元由楼内其他单元来补贴，所以要求越高，每栋楼里的可负担住房越多，但有些楼会算不过账而永远建不起来。取消这项要求能建更多住房，但没有一套是可负担的，也会失去为可负担住房和租金补助提供资金的替代费。',
    'Projekty na 10+ mieszkań, które potrzebują zmiany strefy, miejskiej działki lub miejskich pieniędzy, muszą wynajmować 10–20% lokali poniżej ceny rynkowej, po cenach dla gospodarstw zarabiających średnio 60% mediany dochodu w regionie. Resztę budynku obciąża koszt tych lokali, więc wyższy wymóg oznacza więcej przystępnych mieszkań w każdym budynku, ale niektóre inwestycje przestają się opłacać i nigdy nie powstają. Zniesienie wymogu daje więcej mieszkań, ale żadnego przystępnego, i kończy opłaty zastępcze, które finansują tanie mieszkania i pomoc w czynszu.'),
5: ('Applies to new buildings of 10+', 'Se aplica a edificios nuevos de 10 o más viviendas, con una estimación intermedia (supuesto): sin requisito, unos 20% más de esos edificios; con 10%, unos 10% más; con 30%, unos 5% menos. El modelo del Terner Center para Los Ángeles muestra aproximadamente el doble (398,800 contra 289,000 viviendas sin requisito frente a la regla actual de Los Ángeles). Los estudios de ciudades reales casi siempre encuentran poca o ninguna caída en la construcción total (California, el Área de la Bahía, los condados de Los Ángeles y Orange, Baltimore–Washington), con 5–8% menos viviendas en un estudio de California; los permisos de Portland cayeron mucho tras su regla de 2017, pero ese no es un estudio controlado. Quitarlo construye más viviendas pero ninguna asequible, y elimina las cuotas sustitutivas, que van mitad a construir vivienda asequible y mitad a ayuda con la renta.',
    '适用于 10 套以上的新楼，采用中间估计（假设）：取消要求，这类楼约多建 20%；要求 10%，约多 10%；要求 30%，约少 5%。特纳中心的洛杉矶模型显示的影响约为两倍（无要求时 398,800 套，对比洛杉矶现行规定下的 289,000 套）。对真实城市的研究大多发现总建设量几乎没有下降（加州、湾区、洛杉矶和橙县、巴尔的摩–华盛顿），一项加州研究发现住房少 5–8%；波特兰 2017 年实施规定后许可证大幅下降，但那不是对照研究。取消要求能建更多住房，但没有可负担的，也会失去替代费，这笔钱一半用于建可负担住房，一半用于租金补助。',
    'Dotyczy nowych budynków z 10+ mieszkaniami, według szacunku pośredniego (założenie): bez wymogu takich budynków powstaje ok. 20% więcej, przy 10% ok. 10% więcej, przy 30% ok. 5% mniej. Model Terner Center dla Los Angeles pokazuje mniej więcej dwa razy silniejszy efekt (398 800 wobec 289 000 mieszkań bez wymogu i przy obecnej zasadzie LA). Badania prawdziwych miast zwykle nie znajdują spadku całego budownictwa albo znajdują niewielki (Kalifornia, Bay Area, hrabstwa Los Angeles i Orange, Baltimore–Waszyngton), a jedno kalifornijskie badanie znalazło 5–8% mniej mieszkań; w Portland liczba pozwoleń mocno spadła po zasadzie z 2017, ale to nie było badanie kontrolowane. Zniesienie wymogu daje więcej mieszkań, ale żadnego przystępnego, i kończy opłaty zastępcze, które w połowie idą na budowę tanich mieszkań, a w połowie na pomoc w czynszu.'),
6: ('Mostly underway', 'Casi todo en marcha, 2025', '大部分正在推进，2025', 'W większości w toku, 2025'),
7: ("Mayor Johnson's 2024 report", 'El informe de 2024 del alcalde Johnson proponía 107 mejoras al proceso de aprobación de Chicago; la ciudad dice que 96 estaban en marcha o listas en mayo de 2025. Aprobar un cambio de zonificación tomaba en promedio 116 días en 2017 (Chicago Cityscape).',
    '约翰逊市长 2024 年的报告提出 107 项改进芝加哥审批流程的措施；市政府说到 2025 年 5 月已有 96 项在推进或完成。2017 年分区变更的批准平均需要 116 天（Chicago Cityscape）。',
    'Raport burmistrza Johnsona z 2024 zawierał 107 poprawek do procesu zatwierdzania w Chicago; miasto podaje, że do maja 2025 96 z nich było w toku lub wdrożonych. W 2017 zatwierdzenie zmiany strefy trwało średnio 116 dni (Chicago Cityscape).'),
8: ('Assumption: 10% more projects get built and they arrive', 'Supuesto: se construyen 10% más proyectos y llegan unos 7 meses antes (20% de un proceso de aprobación y construcción de unos tres años). Las investigaciones encuentran 20–25% menos permisos en las metrópolis con aprobaciones lentas.',
    '假设：多建成 10% 的项目，并提前约 7 个月完工（约三年审批加建设时间的 20%）。研究发现，审批慢的都市区许可证少 20–25%。',
    'Założenie: powstaje 10% więcej projektów i są gotowe ok. 7 miesięcy wcześniej (20% z mniej więcej trzyletniego zatwierdzania i budowy). Badania pokazują o 20–25% mniej pozwoleń w metropoliach z powolnym zatwierdzaniem.'),
9: ('Proposed in City Council', 'Propuesto en el Concejo Municipal', '已在市议会提出', 'Zaproponowane w Radzie Miasta'),
10: ("Ald. Napolitano", 'La medida del concejal Napolitano permitiría a los concejales prohibir nuevas rentas de corto plazo precinto por precinto; pasó el comité en junio de 2025. La regla de Nueva York de 2023, que exige que sea la residencia principal, es el modelo más estricto. Chicago tiene unos 11,200 anuncios activos, cerca del 80% de ellos viviendas completas.',
    '纳波利塔诺市议员的提案将允许市议员逐个选区禁止新的短租房源；该提案于 2025 年 6 月通过委员会。纽约 2023 年的"主要住所"规定是更严格的模式。芝加哥约有 11,200 个活跃房源，约 80% 是整套住房。',
    'Projekt radnego Napolitano pozwoliłby radnym zakazywać nowego najmu krótkoterminowego w poszczególnych okręgach wyborczych; przeszedł przez komisję w czerwcu 2025. Surowszym wzorem jest nowojorska zasada z 2023, wymagająca, by lokal był głównym miejscem zamieszkania. Chicago ma ok. 11 200 aktywnych ogłoszeń, z czego ok. 80% to całe mieszkania.'),
11: ('Assumes precinct bans', 'Supone que las prohibiciones por precinto devuelven el 10% de las viviendas completas en anuncio a inquilinos de largo plazo, y que una regla de residencia principal devuelve el 50%.',
    '假设按选区禁止能让 10% 的整套房源回到长租市场，"主要住所"规定能让 50% 回来。',
    'Zakłada, że zakazy w okręgach przywrócą najmowi długoterminowemu 10% ogłoszeń całych mieszkań, a zasada głównego miejsca zamieszkania 50%.'),
12: ('Proposed, hearing', 'Propuesto, audiencia en junio de 2026', '已提出，2026 年 6 月举行听证会', 'Zaproponowane, przesłuchanie w czerwcu 2026'),
13: ('Would let some mid-size', 'Permitiría que algunos edificios de departamentos medianos usen una sola escalera en lugar de dos, lo que hace viables los edificios de 4 a 6 pisos en los lotes angostos de Chicago. Los departamentos de Edificios y de Bomberos se oponen por razones de seguridad.',
    '允许部分中型公寓楼只设一个楼梯而不是两个，这让 4–6 层的楼能建在芝加哥狭窄的地块上。建筑局和消防局以安全为由反对。',
    'Pozwoliłoby części średnich budynków mieszkalnych mieć jedną klatkę schodową zamiast dwóch, dzięki czemu budynki 4–6-piętrowe mieszczą się na wąskich działkach Chicago. Wydział budownictwa i straż pożarna sprzeciwiają się ze względów bezpieczeństwa.'),
14: ('Assumption: 25% more 6-flat', 'Supuesto: se construyen 25% más proyectos de edificios de 6 departamentos y de altura media en lotes de menos de 7,500 pies cuadrados. No afecta a los rascacielos (necesitan dos escaleras en todas partes) ni a los de 3 departamentos (ya pueden tener una), así que no suma nada hasta que zonifiques algunas áreas para edificios de 6 departamentos o de altura media.',
    '假设：在 7,500 平方英尺以下地块上的六户楼和中层楼项目多建成 25%。它不影响高层楼（任何地方都需要两个楼梯）和三户楼（本来就允许一个楼梯），所以在你给某些地区划定六户楼或中层楼分区之前，它不会增加任何住房。',
    'Założenie: na działkach poniżej 7500 stóp kw. powstaje o 25% więcej projektów domów sześciorodzinnych i średniowysokich. Nie dotyczy wieżowców (wszędzie potrzebują dwóch klatek) ani domów trzyrodzinnych (już mogą mieć jedną), więc nic nie dodaje, dopóki nie przeznaczysz jakichś obszarów pod domy sześciorodzinne lub średniowysokie.'),
15: ('Partly passed', 'Aprobado en parte: 34 de 50 distritos', '部分通过：50 个选区中的 34 个', 'Częściowo przyjęte: 34 z 50 okręgów'),
16: ('Coach houses and basement units', 'Las casas de cochera y las unidades en sótanos se volvieron legales el 1 de abril de 2026 en 34 distritos; 14 concejales dejaron fuera sus distritos. El programa piloto de 2021 produjo unos pocos cientos de unidades (373 según The Real Deal). Esto las permitiría por derecho en todos los distritos.',
    '2026 年 4 月 1 日起，马车房和地下室单元在 34 个选区合法；14 位市议员让自己的选区不参加。2021 年的试点只建成了几百个单元（据 The Real Deal 为 373 个）。这项政策会让它们在每个选区都无需审批即可建造。',
    'Domki w podwórzu i mieszkania w suterenach stały się legalne 1 kwietnia 2026 w 34 okręgach; 14 radnych wyłączyło swoje okręgi. Pilotaż z 2021 dał kilkaset lokali (373 według The Real Deal). To dopuściłoby je z mocy prawa w każdym okręgu.'),
17: ('Pilot pace', 'Al ritmo del piloto (cerca del 0.75% de los lotes elegibles en 15 años) en los 50 distritos, el doble al quitar las reglas adicionales.',
    '按试点速度（15 年内约 0.75% 的合格地块）推广到全部 50 个选区，取消额外规定后翻倍。',
    'Tempo pilotażu (ok. 0,75% kwalifikujących się działek w 15 lat) we wszystkich 50 okręgach, podwojone dzięki zniesieniu dodatkowych zasad.'),
18: ('Mostly stuck', 'Casi todos estancados, 2026', '大多停滞，2026', 'W większości utknęło, 2026'),
19: ('Chicago already approved or planned about 31,600', 'Chicago ya aprobó o planeó unas 31,600 viviendas en un puñado de proyectos gigantes: The 78 (10,000), Bronzeville Lakefront en el antiguo sitio de Michael Reese (6,800), el 1901 Project alrededor del United Center (unas 5,000, aunque su zonificación permite hasta 9,463), Cabrini-Green (4,080), Foundry Park en el antiguo sitio de Lincoln Yards (hasta 3,737) y el resto de North Union (2,007). La mayoría está esperando calles, puentes, muros del río o financiamiento faltante. Actívalo y la ciudad paga para destrabarlos.',
    '芝加哥已批准或规划了约 31,600 套住房，集中在几个超大项目里：The 78（10,000 套）、原 Michael Reese 旧址上的 Bronzeville Lakefront（6,800 套）、联合中心周边的 1901 Project（约 5,000 套，但其分区允许多达 9,463 套）、Cabrini-Green（4,080 套）、原 Lincoln Yards 旧址上的 Foundry Park（最多 3,737 套）以及 North Union 的剩余部分（2,007 套）。大多数项目在等道路、桥梁、河堤或资金缺口。打开这项政策，由市政府出钱让它们动起来。',
    'Chicago zatwierdziło lub zaplanowało już ok. 31 600 mieszkań w kilku olbrzymich projektach: The 78 (10 000), Bronzeville Lakefront na dawnym terenie Michael Reese (6800), 1901 Project wokół United Center (ok. 5000, choć strefa pozwala na 9463), Cabrini-Green (4080), Foundry Park na dawnym terenie Lincoln Yards (do 3737) i reszta North Union (2007). Większość czeka na drogi, mosty, nabrzeża albo brakujące finansowanie. Włącz to, a miasto zapłaci, by je odblokować.'),
20: ('Assumption: half of those 31,624', 'Supuesto: la mitad de esas 31,624 viviendas planeadas se construye para 2041 una vez que la ciudad pague la infraestructura. Esa mitad es cerca de una sexta parte de la meta del modo normal y cerca del 5% de la del modo difícil, así que la zonificación de todos los días sigue haciendo casi todo el trabajo. Los edificios morados del mapa muestran cada plan completo construido para 2041, fase por fase, dentro de su zona aprobada y a las alturas que su plan permite (Foundry Park de 8 a 38 pisos al principio y luego torres de 250 a 450 pies; el 1901 Project hasta 660 pies; North Union hasta 695 pies; Bronzeville Lakefront hasta 350 pies en la primera fase; Cabrini-Green sobre todo edificios de seis departamentos, casas adosadas y edificios de altura media). La ubicación exacta de los edificios sigue el plano publicado de cada proyecto.',
    '假设：市政府出资建设基础设施后，这 31,624 套规划住房中的一半在 2041 年前建成。这一半约占普通模式目标的六分之一、困难模式目标的 5%，所以日常分区仍然承担大部分工作。地图上的紫色建筑显示每个项目在 2041 年前按阶段全部建成，位于其获批的分区范围内，高度符合规划（Foundry Park 起初 8 至 38 层，之后是 250–450 英尺的塔楼；1901 Project 最高 660 英尺；North Union 最高 695 英尺；Bronzeville Lakefront 第一阶段最高 350 英尺；Cabrini-Green 主要是六户楼、联排住宅和中层楼）。建筑的具体位置依照各项目公布的场地规划。',
    'Założenie: połowa z tych 31 624 zaplanowanych mieszkań powstaje do 2041, gdy miasto sfinansuje infrastrukturę. Ta połowa to ok. jedna szósta celu trybu normalnego i ok. 5% celu trybu trudnego, więc większość pracy i tak wykonuje codzienne strefowanie. Fioletowe budynki na mapie pokazują każdy plan w całości zbudowany do 2041, etap po etapie, w zatwierdzonej strefie i na wysokościach, na jakie pozwala plan (Foundry Park najpierw 8–38 pięter, potem wieże 250–450 stóp; 1901 Project do 660 stóp; North Union do 695 stóp; Bronzeville Lakefront do 350 stóp w pierwszym etapie; Cabrini-Green głównie domy sześciorodzinne, szeregowce i budynki średniowysokie). Dokładne miejsca budynków odpowiadają opublikowanym planom zagospodarowania każdego projektu.'),
21: ('City is selling lots now', 'La ciudad ya está vendiendo lotes', '市政府正在出售地块', 'Miasto już sprzedaje działki'),
22: ('The city owns more than 7,100', 'La ciudad es dueña de más de 7,100 lotes baldíos, concentrados en Englewood, West Englewood, New City y North Lawndale, y vende algunos por $1 a través de su programa Missing Middle.',
    '市政府拥有 7,100 多块空地，集中在 Englewood、West Englewood、New City 和 North Lawndale，并通过"缺失的中间住房"计划以 1 美元出售其中一些。',
    'Miasto ma ponad 7100 pustych działek, głównie w Englewood, West Englewood, New City i North Lawndale, i sprzedaje część z nich za 1 dolara w programie Missing Middle.'),
23: ('Assumption: half of the lots get a 2-flat', 'Supuesto: en 15 años, la mitad de los lotes recibe un edificio de 2 departamentos.', '假设：15 年内一半的地块建起双户楼。', 'Założenie: w ciągu 15 lat na połowie działek powstaje dom dwurodzinny.'),
24: ('Pilot: Missing Middle', 'Piloto: Missing Middle, 2025–26', '试点：缺失的中间住房，2025–26', 'Pilotaż: Missing Middle, 2025–26'),
25: ('On much of the South and West Sides', 'En gran parte del South Side y del West Side, construir un edificio nuevo de 2 departamentos cuesta más de lo que se vendería, así que los lotes siguen vacíos incluso donde la zonificación ya permite viviendas. El programa Missing Middle de Chicago vende lotes de la ciudad por $1 y cubre hasta $150,000 por vivienda; su cuarta ronda son 62 viviendas en 30 lotes. Además hay unas 31,000 parcelas baldías privadas en la ciudad (Tasador del Condado de Cook, 2025). Esto lleva la idea a esas parcelas.',
    '在南区和西区的大部分地方，新建一栋双户楼的成本高于它的售价，所以即使分区已经允许建房，地块仍然空着。芝加哥的"缺失的中间住房"计划以 1 美元出售市有地块，并为每套住房补贴最多 15 万美元；第四轮是 30 块地上的 62 套住房。市内另有约 31,000 块私人空地（库克县估价办公室，2025）。这项政策把这个做法推广到这些私人地块。',
    'Na dużej części South Side i West Side budowa nowego domu dwurodzinnego kosztuje więcej, niż dałoby się za niego dostać, więc działki stoją puste nawet tam, gdzie strefa pozwala na mieszkania. Program Missing Middle sprzedaje miejskie działki za 1 dolara i pokrywa do 150 000 dolarów na mieszkanie; czwarta runda to 62 mieszkania na 30 działkach. W mieście jest też ok. 31 000 prywatnych pustych działek (asesor hrabstwa Cook, 2025). To rozszerza ten pomysł na nie.'),
26: ('Assumption: at up to $150,000', 'Supuesto: con hasta $150,000 por vivienda, el 15% de las parcelas baldías privadas recibe un edificio de 2 departamentos para 2041 (unas 9,400 viviendas, cerca de $1.4 mil millones en subsidio, o unos $94 millones al año), y los proyectos rezonificados en barrios de mercado débil (demanda menor de 0.9×) tienen 50% más probabilidad de construirse. El mapa muestra los edificios de dos departamentos que se construyen.',
    '假设：每套住房补贴最多 15 万美元，到 2041 年 15% 的私人空地建起双户楼（约 9,400 套，补贴约 14 亿美元，每年约 9,400 万美元），而在市场疲软的社区（需求低于 0.9×）重新分区的项目建成的可能性高 50%。地图显示建成的双户楼。',
    'Założenie: przy dopłacie do 150 000 dolarów na mieszkanie do 2041 na 15% prywatnych pustych działek powstaje dom dwurodzinny (ok. 9400 mieszkań, ok. 1,4 mld dol. dopłat, czyli ok. 94 mln rocznie), a projekty w dzielnicach o słabym rynku (popyt poniżej 0,9×) mają o 50% większą szansę na budowę. Mapa pokazuje powstające domy dwurodzinne.'),
27: ('Reform idea', 'Idea de reforma', '改革设想', 'Pomysł na reformę'),
28: ('Alderpeople can effectively veto', 'Los concejales pueden vetar en la práctica la vivienda en sus distritos. Una investigación federal de HUD de 2023 concluyó que esa práctica bloquea la vivienda asequible (HUD retiró la conclusión en 2025).',
    '市议员实际上可以否决自己选区内的住房项目。2023 年联邦住房和城市发展部（HUD）的调查认定这种做法阻碍了可负担住房（HUD 于 2025 年撤回了这一结论）。',
    'Radni mogą w praktyce zawetować mieszkania w swoich okręgach. Federalne dochodzenie HUD z 2023 uznało, że ta praktyka blokuje tanie mieszkania (HUD wycofał to ustalenie w 2025).'),
29: ('Assumption: 15% more projects get built everywhere', 'Supuesto: se construyen 15% más proyectos en todas partes porque se bloquean menos.', '假设：各地多建成 15% 的项目，因为被阻挡的更少。', 'Założenie: wszędzie powstaje o 15% więcej projektów, bo mniej jest blokowanych.'),
30: ('Minneapolis, 2020', 'Minneapolis, 2020', '明尼阿波利斯，2020', 'Minneapolis, 2020'),
31: ('The 2040 plan allowed', 'El plan 2040 permitió 3 viviendas en cualquier lote y de 3 a 6 pisos en los corredores de transporte; la ciudad eliminó los mínimos de estacionamiento en 2021. De 2017 a 2022 Minneapolis aumentó su vivienda 12% (contra 4% en el resto de Minnesota) y las rentas subieron 1% (contra 14%). El 87% de las viviendas nuevas estaba en edificios de 20 o más unidades; solo el 1% en edificios de 2 a 4 unidades.',
    '2040 规划允许任何地块建 3 套住房，公交走廊上建 3–6 层；该市在 2021 年取消了停车位最低要求。2017 至 2022 年，明尼阿波利斯住房增加 12%（明尼苏达州其他地区为 4%），房租上涨 1%（其他地区为 14%）。87% 的新住房在 20 套以上的楼里；只有 1% 在 2–4 套的楼里。',
    'Plan 2040 dopuścił 3 mieszkania na każdej działce i 3–6 pięter przy korytarzach komunikacyjnych; w 2021 miasto zniosło minimalne normy parkingowe. W latach 2017–2022 liczba mieszkań w Minneapolis wzrosła o 12% (wobec 4% w reszcie Minnesoty), a czynsze o 1% (wobec 14%). 87% nowych mieszkań powstało w budynkach z 20+ lokalami; tylko 1% w budynkach 2–4-lokalowych.'),
32: ('Every lot with 1–4 homes gets 3-flat zoning, corridor', 'Todo lote con 1 a 4 viviendas recibe zonificación de 3 departamentos, los lotes en corredores reciben altura media, y el impulso por quitar el estacionamiento se aplica en toda la ciudad.',
    '每块有 1–4 套住房的地块获得三户楼分区，走廊地块获得中层楼分区，取消停车要求带来的提升适用于全市。',
    'Każda działka z 1–4 mieszkaniami dostaje strefę domu trzyrodzinnego, działki przy korytarzach strefę średniowysoką, a efekt zniesienia parkingów działa w całym mieście.'),
33: ('Cambridge, MA, 2025', 'Cambridge, MA, 2025', '马萨诸塞州剑桥，2025', 'Cambridge, MA, 2025'),
34: ('Cambridge now allows 4 stories', 'Cambridge ahora permite 4 pisos por derecho en casi todos los lotes residenciales (6 con unidades asequibles) y eliminó los límites de tamaño de lote y de número de unidades. Primeros datos: unas 400 viviendas con permiso hasta ahora en 2026, contra unos 350 inicios de obra al año en 2023–25.',
    '剑桥现在几乎所有住宅地块都可以无需审批建 4 层（含可负担单元可建 6 层），并取消了地块面积和单元数量上限。初步数据：2026 年至今约 400 套住房获得许可，而 2023–25 年每年约 350 套开工。',
    'Cambridge pozwala teraz z mocy prawa na 4 piętra na prawie każdej działce mieszkalnej (6 z tanimi mieszkaniami) i zniosło limity wielkości działki i liczby lokali. Pierwsze wyniki: ok. 400 mieszkań z pozwoleniem w 2026 do tej pory, wobec ok. 350 rozpoczętych budów rocznie w latach 2023–25.'),
35: ('Every lot with 1–4 homes gets at least 6-flat', 'Todo lote con 1 a 4 viviendas recibe al menos zonificación de 6 departamentos. Los primeros resultados son pocos, así que tómalo como un "qué pasaría si".',
    '每块有 1–4 套住房的地块至少获得六户楼分区。早期结果还很少，所以把它当作一种假设情景。',
    'Każda działka z 1–4 mieszkaniami dostaje co najmniej strefę domu sześciorodzinnego. Wczesnych wyników jest mało, więc traktuj to jako scenariusz „co by było, gdyby”.'),
36: ('Houston, 1998', 'Houston, 1998 y 2013', '休斯敦，1998 和 2013', 'Houston, 1998 i 2013'),
37: ('Houston cut its minimum lot size', 'Houston redujo su tamaño mínimo de lote de 5,000 a 3,500 pies cuadrados por derecho, y hasta 1,400 en algunas subdivisiones. Se han construido casi 80,000 viviendas en lotes pequeños, y las casas adosadas que reemplazaron casas unifamiliares tenían un valor tasado medio de $340,000 contra $545,000 de otras casas nuevas.',
    '休斯敦把无需审批的最小地块面积从 5,000 平方英尺降到 3,500，部分分区低至 1,400。小地块上已建了近 80,000 套住房，取代独栋房的联排住宅估价中位数为 34 万美元，而其他新房为 54.5 万美元。',
    'Houston zmniejszył minimalną wielkość działki z 5000 do 3500 stóp kw. z mocy prawa, a w niektórych podziałach nawet do 1400. Na małych działkach powstało prawie 80 000 domów, a szeregowce w miejsce domów jednorodzinnych miały medianę wartości szacunkowej 340 000 dol. wobec 545 000 dol. dla innych nowych domów.'),
38: ('Assumption: 20% more 3-flat', 'Supuesto: 20% más proyectos de 3 y 6 departamentos en lotes de 5,000 pies cuadrados o más, que pueden dividirse en casas adosadas.',
    '假设：在 5,000 平方英尺以上的地块上，三户楼和六户楼项目多 20%，这些地块可以分成联排住宅。',
    'Założenie: o 20% więcej projektów domów trzy- i sześciorodzinnych na działkach od 5000 stóp kw., które można podzielić na szeregowce.'),
39: ('Buffalo 2017', 'Buffalo 2017, Austin 2023', '布法罗 2017，奥斯汀 2023', 'Buffalo 2017, Austin 2023'),
40: ('Chicago dropped parking mandates', 'Chicago eliminó la exigencia de estacionamiento cerca del transporte; Buffalo, Minneapolis y Austin la eliminaron en toda la ciudad. En Buffalo, los proyectos de uso mixto construyeron 53% menos espacios de los que exigían las reglas anteriores. La renta media de Austin bajó de $1,546 a $1,296 (2021–2026) en medio de una construcción récord.',
    '芝加哥取消了公交附近的停车位强制要求；布法罗、明尼阿波利斯和奥斯汀在全市取消。在布法罗，混合用途项目建的车位比旧规定要求的少 53%。在创纪录的建设中，奥斯汀的租金中位数从 1,546 美元降到 1,296 美元（2021–2026）。',
    'Chicago zniosło obowiązek budowy parkingów przy komunikacji; Buffalo, Minneapolis i Austin zniosły go w całym mieście. W Buffalo projekty wielofunkcyjne zbudowały o 53% mniej miejsc, niż wymagały stare zasady. Mediana czynszu w Austin spadła z 1546 do 1296 dolarów (2021–2026) przy rekordowym budownictwie.'),
41: ('Assumption: 10% more projects get built on lots outside', 'Supuesto: se construyen 10% más proyectos en lotes fuera de las zonas de transporte, donde todavía se exige estacionamiento.',
    '假设：在公交区域以外、仍有停车要求的地块上多建成 10% 的项目。',
    'Założenie: o 10% więcej projektów na działkach poza obszarami przy komunikacji, gdzie wymogi parkingowe nadal obowiązują.'),
42: ('Texas, 2025', 'Texas, 2025', '得克萨斯，2025', 'Teksas, 2025'),
43: ('Texas SB 840', 'La ley SB 840 de Texas permite construir departamentos y uso mixto en terrenos con zonificación comercial sin rezonificar. Un informe de una coalición cuenta más de 1,250 viviendas posibles directamente en su primer año.',
    '得州 SB 840 法案允许在商业分区土地上直接建公寓和混合用途楼，无需重新分区。一份联盟报告统计，第一年直接促成了 1,250 多套住房。',
    'Teksańska ustawa SB 840 pozwala budować mieszkania i budynki wielofunkcyjne na gruntach handlowych bez zmiany strefy. Raport koalicji liczy ponad 1250 mieszkań, które umożliwiła bezpośrednio w pierwszym roku.'),
44: ("Lots on Chicago's commercial corridors", 'Los lotes en los corredores comerciales de Chicago reciben al menos zonificación de 6 departamentos.', '芝加哥商业走廊上的地块至少获得六户楼分区。', 'Działki przy ulicach handlowych Chicago dostają co najmniej strefę domu sześciorodzinnego.'),
45: ('Vancouver, 2017', 'Vancouver, 2017', '温哥华，2017', 'Vancouver, 2017'),
46: ('Vancouver taxes homes left empty', 'Vancouver cobra un impuesto a las viviendas que se dejan vacías (hoy 3% del valor). Las viviendas declaradas vacías bajaron 67% de 2017 a 2024 y el impuesto ha aportado $194 millones a la vivienda asequible. Chicago tiene unas 60,000 viviendas que el Censo cuenta como "otras vacantes".',
    '温哥华对空置住房征税（现为房价的 3%）。2017 至 2024 年申报空置的住房减少 67%，这项税已为可负担住房提供 1.94 亿美元。芝加哥约有 60,000 套被人口普查列为"其他空置"的住房。',
    'Vancouver opodatkowuje mieszkania pozostawione puste (dziś 3% wartości). Liczba zgłoszonych pustostanów spadła o 67% w latach 2017–2024, a podatek dał 194 mln dol. na tanie mieszkania. Chicago ma ok. 60 000 mieszkań, które spis ludności liczy jako „inne puste”.'),
47: ("Assumption: 10% of Chicago's 'other vacant'", 'Supuesto: el 10% de las viviendas "otras vacantes" de Chicago vuelve a usarse. Muchas están en mal estado, así que es deliberadamente moderado.',
    '假设：芝加哥 10% 的"其他空置"住房重新投入使用。其中很多状况很差，所以这个估计刻意保守。',
    'Założenie: 10% „innych pustych” mieszkań w Chicago wraca do użytku. Wiele jest w złym stanie, więc szacunek jest celowo ostrożny.'),
48: ('Montgomery County, MD, 2021', 'Condado de Montgomery, MD, 2021', '马里兰州蒙哥马利县，2021', 'Hrabstwo Montgomery, MD, 2021'),
49: ("Montgomery County's $100M", 'El fondo rotatorio de $100 millones del condado de Montgomery (el modelo de Green Social Housing de Chicago) tiene más de 1,100 viviendas construidas o en obra y apunta a 6,000 en 20 años, al menos 30% asequibles. El fondo de Chicago es de $135 millones.',
    '蒙哥马利县 1 亿美元的循环基金（芝加哥绿色社会住房的样板）已建成或在建 1,100 多套住房，目标是 20 年内 6,000 套，至少 30% 为可负担住房。芝加哥的基金是 1.35 亿美元。',
    'Odnawialny fundusz hrabstwa Montgomery na 100 mln dol. (wzór dla chicagowskiego Green Social Housing) ma ponad 1100 mieszkań gotowych lub w budowie i celuje w 6000 w ciągu 20 lat, z czego co najmniej 30% przystępnych. Fundusz Chicago ma 135 mln dol.'),
50: ("Adds $270M to Chicago's fund", 'Agrega $270 millones al fondo de Chicago al ritmo que se propone el condado de Montgomery: unas 12,150 viviendas en 15 años, 30% asequibles.', '按蒙哥马利县的目标速度，向芝加哥的基金增加 2.7 亿美元：15 年约 12,150 套住房，30% 可负担。', 'Dodaje 270 mln dol. do funduszu Chicago w tempie, jakie zakłada hrabstwo Montgomery: ok. 12 150 mieszkań w 15 lat, 30% przystępnych.'),
51: ('Chicago, 1970s', 'Chicago, de los años 70 a los 2010', '芝加哥，1970 年代至 2010 年代', 'Chicago, lata 70. – 2010.'),
52: ('Since the 1970s, Chicago alderpeople have downzoned', 'Desde los años 70, los concejales de Chicago han bajado la zonificación de decenas de barrios, casi siempre a pedido de los vecinos. De 1990 a 2010, las zonas del North Side y del centro con zonificación reducida aumentaron su vivienda 1.8%, mientras que zonas parecidas sin reducción crecieron 9.6%. Las zonas con zonificación reducida también perdieron viviendas de renta y se asociaron con valores de casas más altos.',
    '自 1970 年代以来，芝加哥市议员下调了几十个社区的分区，通常应居民要求。1990 至 2010 年，北区和市中心被下调分区的地方住房只增加了 1.8%，而未下调的类似地区增加了 9.6%。被下调分区的地方还失去了出租住房，并与更高的房价相关。',
    'Od lat 70. radni Chicago obniżyli strefy w dziesiątkach dzielnic, zwykle na prośbę sąsiadów. W latach 1990–2010 obszary North Side i centrum z obniżoną strefą zwiększyły liczbę mieszkań o 1,8%, a podobne obszary bez obniżenia o 9,6%. Obszary z obniżoną strefą straciły też mieszkania na wynajem i wiązały się z wyższymi cenami domów.'),
53: ('Assumption: a new round of downzoning', 'Supuesto: una nueva ronda de reducción de zonificación recorta en 25% las viviendas que Chicago construye de todos modos. Las zonas que rezonifiques conservan tu zonificación.',
    '假设：新一轮下调分区让芝加哥原本就会建的住房减少 25%。你重新分区的地方保留你的分区。',
    'Założenie: nowa runda obniżania stref zmniejsza o 25% liczbę mieszkań, które Chicago i tak buduje. Obszary, którym zmienisz strefę, zachowują twoją strefę.'),
54: ('Chicago ended them', 'Chicago los eliminó, 2025', '芝加哥已取消，2025', 'Chicago je zniosło, 2025'),
55: ('In July 2025 Chicago voted', 'En julio de 2025 Chicago votó para eliminar la exigencia de estacionamiento cerca del transporte, cerca del 74% de la ciudad. Volver a exigirlo significa que cada edificio nuevo tiene que reservar espacio para coches otra vez. El estacionamiento en garaje suma unos $1,700 al año, o 17% de la renta, a un departamento típico; incluso los inquilinos sin coche pagan unos $621 al año por él.',
    '2025 年 7 月，芝加哥投票取消了公交附近的停车位要求，覆盖全市约 74% 的面积。恢复这些要求意味着每栋新楼又要腾出空间给车。车库停车让一套普通公寓每年多花约 1,700 美元，相当于租金的 17%；即使没有车的租户每年也要为此付约 621 美元。',
    'W lipcu 2025 Chicago przegłosowało zniesienie wymogów parkingowych przy komunikacji, na ok. 74% miasta. Przywrócenie ich oznacza, że każdy nowy budynek znów musi wygospodarować miejsce na samochody. Parking w garażu dokłada typowemu mieszkaniu ok. 1700 dol. rocznie, czyli 17% czynszu; nawet najemcy bez samochodu płacą za niego ok. 621 dol. rocznie.'),
56: ('Assumption: 15% fewer rezoned projects', 'Supuesto: se construyen 15% menos proyectos rezonificados (el estacionamiento come espacio del lote y presupuesto) y 10% menos de las viviendas que Chicago construye de todos modos. Desactiva "Sin mínimos de estacionamiento en ningún lugar".',
    '假设：重新分区的项目少建成 15%（停车位占用地块空间和预算），芝加哥原本就会建的住房少 10%。会关闭"任何地方都不设停车位最低要求"。',
    'Założenie: powstaje o 15% mniej projektów po zmianie strefy (parking zjada miejsce na działce i budżet) i o 10% mniej mieszkań, które Chicago i tak buduje. Wyłącza „Bez minimalnych norm parkingowych nigdzie”.'),
57: ('Chicago, 606 & Pilsen', 'Chicago, el 606 y Pilsen, 2021', '芝加哥，606 步道和皮尔森，2021', 'Chicago, 606 i Pilsen, 2021'),
58: ('Since 2021 Chicago has charged a fee', 'Desde 2021 Chicago cobra una cuota por demoler viviendas cerca del sendero 606 y en Pilsen, para frenar el aburguesamiento; desde 2024 es de $20,000 por vivienda perdida o $60,000 por edificio. Las demoliciones ahí bajaron 88% y 25% el primer año. Conserva los edificios viejos, pero por cada uno que se conserva no se construye uno más grande. Las investigaciones encuentran que las metrópolis con aprobaciones lentas reciben 20–25% menos permisos.',
    '自 2021 年起，芝加哥对拆除 606 步道附近和皮尔森的住房收费，以减缓士绅化；自 2024 年起，每拆一套住房收 2 万美元，或每栋楼 6 万美元。第一年那里的拆除分别下降了 88% 和 25%。这保住了老房子，但每保留一栋，就少建一栋更大的楼。研究发现，审批慢的都市区许可证少 20–25%。',
    'Od 2021 Chicago pobiera opłatę za wyburzanie domów przy szlaku 606 i w Pilsen, by spowolnić gentryfikację; od 2024 to 20 000 dol. za każde utracone mieszkanie albo 60 000 dol. za budynek. Wyburzenia spadły tam w pierwszym roku o 88% i 25%. Stare budynki zostają, ale w miejsce każdego zachowanego nie powstaje większy. Badania pokazują o 20–25% mniej pozwoleń w metropoliach z powolnym zatwierdzaniem.'),
59: ('Assumption: 20% fewer rezoned projects', 'Supuesto: se construyen 20% menos proyectos rezonificados y llegan 25% más tarde (algunos se pasan de 2041), y 15% menos de las viviendas que Chicago construye de todos modos.',
    '假设：重新分区的项目少建成 20%，并推迟 25% 完工（部分拖到 2041 年以后），芝加哥原本就会建的住房少 15%。',
    'Założenie: powstaje o 20% mniej projektów po zmianie strefy i są gotowe o 25% później (część po 2041), a mieszkań, które Chicago i tak buduje, jest o 15% mniej.'),
60: ('Rent control, including', 'Control de rentas, incluidos los edificios nuevos', '房租管制，包括新楼', 'Kontrola czynszów, także w nowych budynkach'),
61: ('Banned in Illinois', 'Prohibido en Illinois desde 1997', '伊利诺伊州自 1997 年起禁止', 'Zakazana w Illinois od 1997'),
62: ('Illinois has barred cities', 'Illinois prohíbe a las ciudades limitar las rentas desde 1997, y cada tanto vuelven proyectos de ley para levantar la prohibición. El control de rentas sí ayuda a quienes ya tienen vivienda: en San Francisco, los inquilinos cubiertos tenían casi 20% más probabilidad de quedarse. Pero los propietarios cubiertos por la ley redujeron su oferta de renta 15%, lo que subió las rentas de toda la ciudad 5.1%. St. Paul limitó las rentas al 3% en 2021, incluidos los edificios nuevos; los permisos bajaron de más de 2,000 al año a unos 1,200 en 2022–23. Desde entonces la ciudad exentó toda la construcción nueva.',
    '自 1997 年起，伊利诺伊州禁止城市限制房租，解除禁令的法案不断被提出。房租管制确实帮助已经有房的人：在旧金山，受保护的租户留住的可能性高近 20%。但受法律约束的房东把出租房源减少了 15%，推高全市房租 5.1%。圣保罗在 2021 年把房租涨幅限制在 3%，新楼也包括在内；许可证从每年 2,000 多份降到 2022–23 年的约 1,200 份。此后该市豁免了所有新建房。',
    'Od 1997 Illinois zabrania miastom ograniczania czynszów, a projekty zniesienia zakazu ciągle wracają. Kontrola czynszów pomaga tym, którzy już mają mieszkanie: w San Francisco objęci nią najemcy mieli prawie 20% większą szansę zostać na miejscu. Ale właściciele objęci ustawą zmniejszyli podaż mieszkań na wynajem o 15%, co podniosło czynsze w całym mieście o 5,1%. St. Paul ograniczył podwyżki do 3% w 2021, łącznie z nowymi budynkami; liczba pozwoleń spadła z ponad 2000 rocznie do ok. 1200 w latach 2022–23. Od tamtej pory miasto zwolniło całe nowe budownictwo.'),
63: ('Assumption: 40% fewer rezoned projects', 'Supuesto: se construyen 40% menos proyectos rezonificados de 3 o más viviendas (cerca de la caída del primer año de St. Paul) y 30% menos de las viviendas que Chicago construye de todos modos. La simulación no cuenta el beneficio real para los inquilinos que se quedan.',
    '假设：重新分区的 3 套以上住房项目少建成 40%（约等于圣保罗第一年的降幅），芝加哥原本就会建的住房少 30%。模拟没有计入留下来的租户得到的真实好处。',
    'Założenie: powstaje o 40% mniej projektów 3+ mieszkań po zmianie strefy (mniej więcej spadek z pierwszego roku w St. Paul) i o 30% mniej mieszkań, które Chicago i tak buduje. Symulacja nie liczy realnej korzyści dla najemców, którzy zostają.'),
64: ('Los Angeles, 2023', 'Los Ángeles, 2023', '洛杉矶，2023', 'Los Angeles, 2023'),
65: ("LA's Measure ULA", 'La Medida ULA de Los Ángeles cobra un impuesto de 4% a las ventas de propiedades de más de unos $5 millones y de 5.5% a las de más de $10 millones, para pagar vivienda. Las ventas grandes cayeron cerca de la mitad. Investigadores de UCLA estimaron primero 18% menos departamentos en edificios de 20 o más (unos 1,910 al año); su actualización de 2026 estima unos 31% menos, cerca de 1,900 al año, y el tamaño del efecto todavía se discute. Los votantes de Chicago rechazaron una versión (Bring Chicago Home) en 2024, 53% a 47%.',
    '洛杉矶的 ULA 提案对 500 万美元以上的房产交易征收 4% 的税，1,000 万美元以上征收 5.5%，用于住房。大额交易减少了约一半。加州大学洛杉矶分校的研究者最初估计 20 套以上楼里的公寓减少 18%（每年约 1,910 套）；他们 2026 年的更新估计减少约 31%，每年约 1,900 套，影响大小仍有争议。芝加哥选民在 2024 年以 53% 对 47% 否决了一个类似版本（Bring Chicago Home）。',
    'Measure ULA w Los Angeles opodatkowuje sprzedaż nieruchomości powyżej ok. 5 mln dol. stawką 4%, a powyżej 10 mln dol. stawką 5,5%, na rzecz mieszkalnictwa. Duże transakcje spadły mniej więcej o połowę. Badacze z UCLA najpierw oszacowali o 18% mniej mieszkań w budynkach 20+ (ok. 1910 rocznie); w aktualizacji z 2026 szacują ok. 31% mniej, ok. 1900 rocznie, a skala efektu wciąż jest przedmiotem sporu. Wyborcy w Chicago odrzucili podobną wersję (Bring Chicago Home) w 2024, 53% do 47%.'),
66: ('Assumption: 18% fewer rezoned projects', 'Supuesto: se construyen 18% menos proyectos rezonificados de 20 o más viviendas (la primera estimación, más pequeña, de UCLA) y 5% menos de las viviendas que Chicago construye de todos modos.',
    '假设：重新分区的 20 套以上住房项目少建成 18%（加州大学洛杉矶分校较小的第一次估计），芝加哥原本就会建的住房少 5%。',
    'Założenie: powstaje o 18% mniej projektów 20+ mieszkań po zmianie strefy (pierwszy, mniejszy szacunek UCLA) i o 5% mniej mieszkań, które Chicago i tak buduje.'),
67: ('Adds nothing yet: it only helps 6-flats', 'Aún no suma nada: solo ayuda a edificios de 6 departamentos y de altura media en lotes de menos de 7,500 pies cuadrados. Zonifica algunas áreas para esos edificios y empieza a contar.',
    '暂时不增加住房：它只帮助 7,500 平方英尺以下地块上的六户楼和中层楼。给某些地区划定这类分区，它就会起作用。',
    'Na razie nic nie dodaje: pomaga tylko domom sześciorodzinnym i średniowysokim na działkach poniżej 7500 stóp kw. Wyznacz pod nie jakieś obszary, a zacznie działać.'),
68: ('Adds nothing yet: it speeds up', 'Aún no suma nada: acelera proyectos en las áreas que has rezonificado. Rezonifica algo primero.', '暂时不增加住房：它加快你重新分区地方的项目。先给某个地方重新分区。', 'Na razie nic nie dodaje: przyspiesza projekty na obszarach, którym zmieniłeś strefę. Najpierw zmień jakąś strefę.'),
69: ('Adds nothing yet: it only helps 3-flat', 'Aún no suma nada: solo ayuda a la zonificación de 3 y 6 departamentos en lotes de 5,000 pies cuadrados o más.', '暂时不增加住房：它只帮助 5,000 平方英尺以上地块的三户楼和六户楼分区。', 'Na razie nic nie dodaje: pomaga tylko strefom domów trzy- i sześciorodzinnych na działkach od 5000 stóp kw.'),
70: ('Adds nothing yet: it only helps rezoned lots outside', 'Aún no suma nada: solo ayuda a lotes rezonificados fuera de las zonas de transporte, donde todavía hay reglas de estacionamiento.', '暂时不增加住房：它只帮助公交区域以外、仍有停车规定的重新分区地块。', 'Na razie nic nie dodaje: pomaga tylko działkom po zmianie strefy poza obszarami przy komunikacji, gdzie wciąż obowiązują zasady parkingowe.'),
71: ('Adds nothing with your map', 'No suma nada con tu mapa: tus corredores ya tienen zonificación de 6 departamentos o más alta.', '在你的地图上不增加住房：你的走廊已经是六户楼或更高的分区。', 'Przy twojej mapie nic nie dodaje: twoje korytarze mają już strefę domu sześciorodzinnego lub wyższą.'),
72: ('Adds nothing beyond', 'No suma nada más allá de lo que tu mapa ya permite.', '不会超出你的地图已经允许的范围。', 'Nie dodaje nic ponad to, na co już pozwala twoja mapa.'),
})
